from pathlib import Path
import json
p=Path('笔记同步助手/2026-06-05/2026-06-05 工作看板.canvas')
data=json.loads(p.read_text(encoding='utf-8'))
ids={n['id'] for n in data['nodes']}
missing_files=[]
for n in data['nodes']:
    if n.get('type')=='file':
        path=Path(n['file'])
        if not path.exists():
            missing_files.append(n['file'])
missing_edges=[]
for e in data['edges']:
    if e['fromNode'] not in ids or e['toNode'] not in ids:
        missing_edges.append(e['id'])
if missing_files:
    raise SystemExit('Missing files: '+', '.join(missing_files))
if missing_edges:
    raise SystemExit('Missing edge nodes: '+', '.join(missing_edges))
print('Canvas JSON valid. File nodes checked:', sum(1 for n in data['nodes'] if n.get('type')=='file'), 'Edges checked:', len(data['edges']))
